def picture():
    """the start-up picture (PIL Image), or None if this file was changed"""
    raw = zlib.decompress(base64.b85decode("".join(_DATA)))[::-1]
    if hashlib.sha256(raw).hexdigest() != _SUM:
        return None
    from PIL import Image
    return Image.open(io.BytesIO(raw))
